import{_ as i,l,o as e,c as n,v as t,p as s,x as o,d,i as h,S as _}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"波动率因子模型","description":"","frontmatter":{"title":"波动率因子模型","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/vol-factor-model.md","filePath":"quant/vol-factor-model.md","lastUpdated":1789023840000}'),m={name:"quant/vol-factor-model.md"};function p(E,a,A,c,f,B){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="波动率因子模型" tabindex="-1">波动率因子模型 <a class="header-anchor" href="#波动率因子模型" aria-label="Permalink to &quot;波动率因子模型&quot;">​</a></h1><div class="epigraph"><p>许多资产的条件方差一起涨落；用少数共同因子承担这部分，特异波动再各自一方程，维数从 BEKK 的矩阵落到因子载荷。</p><footer>—— Diebold and Nerlove, The Dynamics of Exchange Rate Volatility: A Multivariate Latent Factor ARCH Model, Journal of Applied Econometrics, 1989；因子 ARCH 见 Engle, Ng and Rothschild</footer></div><p><a href="/quant/bekk-mgarch">BEKK</a> 在小 \\(k\\) 上给出满 \\(H_t\\)，大 \\(k\\) 不可行。收益的因子模型 \\(r_t=\\beta f_t+u_t\\) 已经把均值–协方差的大部分写成 \\(\\beta\\,\\mathrm{Var}(f_t)\\,\\beta^\\top+\\mathrm{Var}(u_t)\\)。波动因子模型让 \\(\\mathrm{Var}(f_t)\\) 与可能的共同特异波动再随时间变。Diebold–Nerlove 对汇率用潜因子 ARCH；Engle–Ng–Rothschild 把因子 ARCH 写成可估形式。本课缺口：用<strong>共同波动</strong>代替满矩阵 GARCH。下一课日内季节性把「共同」进一步拆成钟内模式——对象从日 \\(H_t\\) 转到一天之内的确定性形状。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>股票在危机里相关升高，主要是共同因子方差升高，不是 3000 只股票的 BEKK 溢出。问题是估计：因子可观测（指数、FF 因子）还是潜的（滤波、PCA on squares）。可观测因子：对因子估 <a href="/quant/garch">GARCH</a>/HAR，个股 \\(\\sigma_{i,t}^2=\\beta_i^2\\sigma_{f,t}^2+\\sigma_{e,i,t}^2\\)，特异再一元。潜因子：平方或 RV 的截面 PCA，取前几个成分当波动因子（类似 Connor–Korajczyk，但对象是二阶）。</p><p>对象是条件协方差的低秩部分加对角特异，不是已实现协方差的高频估计。与 <a href="/quant/cov-shrinkage">协方差收缩</a> 分工：收缩是静态 \\(\\Sigma\\) 的正则；本课是动态 \\(H_t\\) 的因子结构。</p><h3 id="载荷时变" tabindex="-1">载荷时变 <a class="header-anchor" href="#载荷时变" aria-label="Permalink to &quot;载荷时变&quot;">​</a></h3><p>\\(\\beta\\) 若时变（Kalman、滚动），共同波动对个股 \\(H_t\\) 的映射跟着变。危机里 \\(\\beta\\) 升与 \\(\\sigma_f\\) 升会纠缠。应声明：固定 \\(\\beta\\) + 时变因子方差，还是两者都变。两者都变则识别弱，需要状态空间约束，见 <a href="/quant/state-space-kalman-smoother">Kalman</a>。</p><p><span class="marginnote">用指数已实现方差当 \\(\\sigma_f^2\\)，再用日 \\(\\beta\\) 映射到个股，是工程上最稳的一档。个股 RV 对噪声更敏感，见 rv-noise。先共同、后特异。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>可观测因子。</strong> 市场 + 若干行业。因子方差：GARCH 或 HAR-RV。特异：对角 GARCH 或异质 HAR。相关升来自 \\(\\sigma_f\\) 升。评估：组合方差的 QLIKE，不是个股对角。</p><p><strong>潜因子。</strong> 对 RV 面板或对 \\(|r|\\) 做动态因子（Barigozzi–Hallin 一类）。滞后阶、因子个数用信息准则或边缘似然（接贝叶斯比较的精神）。平方的 PCA 会被离群日主导，应稳健或用 log RV。</p><p><strong>与 DCC。</strong> DCC 让相关慢变、方差各走各的。因子模型让相关变化主要由因子方差驱动，更省、更符合「危机时相关升」。DCC 能描述因子结构解释不了的相关漂移。可以：因子 \\(H_t\\) + 残差 DCC。参数仍要克制。</p><h3 id="定价与风险" tabindex="-1">定价与风险 <a class="header-anchor" href="#定价与风险" aria-label="Permalink to &quot;定价与风险&quot;">​</a></h3><p>条件 CAPM 说 \\(\\lambda\\) 或 \\(\\beta\\) 时变。波动因子给出 \\(\\beta_i^2\\sigma_{f,t}^2\\) 作为时变风险。是否定价是 <a href="/quant/conditional-capm">条件 CAPM</a> 与 FM 的对象，本课只提供 \\(H_t\\) 的构造。不要把波动因子载荷直接叫风险价格。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>共同冲击抬高 \\(f\\) 的方差，所有暴露 \\(\\beta_i\\) 的资产方差与协方差同比例升（固定 \\(\\beta\\) 时）。这自动产生相关的逆周期：\\(\\mathrm{Corr}_{ij}=\\beta_i\\beta_j\\sigma_f^2/\\sqrt{h_i h_j}\\) 在 \\(\\sigma_f\\) 大时升高（若特异不太一起升）。机制是低秩，不是两两溢出。BEKK 的 \\(A_{ij}\\) 试图描述的许多「溢出」，其实是共同因子。</p><p>测量：日平方当因子方差，噪声大，共同成分仍相对可估（截面平均）。个股特异噪声大，特异 GARCH 的 \\(\\alpha\\) 往往不稳——应对特异再收缩，接经验贝叶斯课。</p><p><span class="marginnote">行业因子既是收益因子也是波动因子。能源冲击日，能源股共同方差升，市场因子不够。因子名单应与均值模型对齐，否则 \\(H_t\\) 的低秩部分指错空间。</span></p><h3 id="到日内季节性的交接" tabindex="-1">到日内季节性的交接 <a class="header-anchor" href="#到日内季节性的交接" aria-label="Permalink to &quot;到日内季节性的交接&quot;">​</a></h3><p>日 \\(H_t\\) 假定一天一个协方差。开盘 \\(\\sigma\\) 是收盘的数倍，把季节性塞进日 GARCH 会污染 \\(\\alpha,\\beta\\)。下一课把钟内确定性模式除掉，再谈随机波动与 RV。因子结构在日内同样存在（开盘共同忙），但先估季节，再估随机。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>潜因子个数随样本变，滚动重估会导致 \\(H_t\\) 跳。IPO、退市让 \\(\\beta\\) 面板非平衡。外汇、商品的「市场因子」不如股票清晰，Diebold–Nerlove 的潜因子更对口。</p><p>工程：股票用可观测指数 RV + \\(\\beta\\) + 对角特异；汇率用低维潜因子 ARCH。评估组合 QLIKE。不要对个股满 BEKK。不要用 PCA on raw returns 的第一主成分当波动因子而不看平方——那是均值因子，对象不同。下一课：把一天之内的确定性波动形状从随机部分拆开。</p>',24)),(e(),s(_,null,{default:o(()=>[h(r,{id:"mermaid-70",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%94%B6%E7%9B%8A%E5%90%91%E9%87%8F%22%5D%20--%3E%20F%5B%22%E5%9B%A0%E5%AD%90%20f%EF%BC%88%E5%8F%AF%E8%A7%82%E6%B5%8B%E6%88%96%E6%BD%9C%EF%BC%89%22%5D%0A%20%20F%20--%3E%20VF%5B%22%E5%9B%A0%E5%AD%90%E6%96%B9%E5%B7%AE%20%CF%83%C2%B2_f%2Ct%22%5D%0A%20%20VF%20--%3E%20H%5B%22%E4%BD%8E%E7%A7%A9%3A%20%CE%B2%20%CF%83%C2%B2_f%20%CE%B2'%22%5D%0A%20%20R%20--%3E%20ID%5B%22%E7%89%B9%E5%BC%82%E5%AF%B9%E8%A7%92%20GARCH%20%2F%20HAR%22%5D%0A%20%20ID%20--%3E%20H2%5B%22H_t%20%3D%20%E4%BD%8E%E7%A7%A9%20%2B%20%E5%AF%B9%E8%A7%92%22%5D%0A%20%20H%20--%3E%20H2%0A%20%20H2%20--%3E%20K%5B%22k%20%E5%A4%A7%E6%97%B6%E6%9B%BF%E4%BB%A3%E6%BB%A1%20BEKK%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>条件协方差的共同部分用少数波动因子承担，特异走对角，避免满 BEKK。</li><li>可观测因子加指数 RV 是稳妥工程；潜因子对汇率等无单一指数时需要。</li><li>危机相关升高可以是 \\(\\sigma_f\\) 升高的代数结果，不必两两溢出。</li><li>\\(\\beta\\) 与 \\(\\sigma_f\\) 同时时变会弱识别；载荷空间应与均值因子对齐。</li><li>出处：Diebold and Nerlove, <em>Journal of Applied Econometrics</em>, 1989；Engle, Ng and Rothschild, <em>Journal of Econometrics</em>, 1990；动态因子后续见 Barigozzi and Hallin 等。</li></ul>',2))])}const b=i(m,[["render",p]]);export{C as __pageData,b as default};
